import {defaults,limits,validate,build,binarySTL,volume} from './geometry.js';
import {Viewer} from './viewer.js';
import {kit,scadSource,manifest} from './exports.js';
const $=id=>document.getElementById(id);let model,viewer,selected='',timer,busy=false,valid=false;
const kernelPromise=window.PETAL_SCAD?Promise.resolve(window.PETAL_SCAD):fetch('kernel.scad').then(r=>{if(!r.ok)throw Error('OpenSCAD source could not load. Reload the page.');return r.text();});kernelPromise.catch(()=>{});
for(let n=6;n<=32;n+=2)$('sectors').add(new Option(`${n} petals`,String(n)));for(let n=1;n<=12;n++)$('rows').add(new Option(`${n} ring${n===1?'':'s'}`,String(n)));
try{viewer=new Viewer($('canvas'));}catch(e){$('view-error').hidden=false;$('view-error').textContent=e.message;}
function read(){return Object.fromEntries(Object.keys(defaults).map(k=>[k,$(k).type==='checkbox'?Number($(k).checked):$(k).value===''?NaN:Number($(k).value)]));}
function setFields(p){for(const k in defaults){if($(k).type==='checkbox')$(k).checked=Boolean(p[k]);else $(k).value=p[k];if($(k+'-range'))$(k+'-range').value=p[k];}syncBed();$('facet-settings').hidden=!p.rearStyle;$('rib-settings').hidden=!p.supports;$('joint-settings').hidden=!p.jointStyle;$('spacing-settings').hidden=!p.adaptiveJoints;}
function syncBed(){const v=[$('bedX').value,$('bedY').value,$('bedZ').value].join(',');$('bedPreset').value=[...$('bedPreset').options].some(o=>o.value===v)?v:'custom';}
function buttons(){for(const id of ['export-all','export-scad'])$(id).disabled=!valid||busy;$('export-part').disabled=!valid||busy||!selected;}
function profile(m){const D=m.p.diameter,f=m.focal,d=m.depth,scale=Math.min(218/D,82/f),cx=130,cy=102;let path='';for(let i=0;i<=60;i++){const x=-D/2+D*i/60,z=x*x/(4*f);path+=`${i?'L':'M'}${(cx+x*scale).toFixed(2)},${(cy-z*scale).toFixed(2)} `;}$('profile').innerHTML=`<line x1="${cx}" y1="12" x2="${cx}" y2="106" stroke="#48484f" stroke-dasharray="3 4"/><path d="${path}" fill="none" stroke="#adc4f4" stroke-width="2"/><circle cx="${cx}" cy="${cy-f*scale}" r="3" fill="#e3b66e"/><text x="${cx+9}" y="${cy-f*scale+4}" fill="#bdbdc7" font-family="monospace" font-size="12">focus</text><text x="8" y="15" fill="#92929f" font-family="monospace" font-size="11">CROSS-SECTION</text>`;}
function select(id){selected=id===selected?'':id;for(const b of $('parts').children)b.setAttribute('aria-pressed',b.dataset.id===selected?'true':'false');const p=model?.parts.find(x=>x.id===selected);const facts=p?[p.dim.map(x=>x.toFixed(1)).join(' × ')+' mm · '+(volume(p.mesh)/1000).toFixed(1)+' cm³']:[];if(p?.kind==='panel'){if(p.wallRange)facts.push('Wall '+p.wallRange.map(x=>x.toFixed(1)).join('–')+' mm');facts.push('Tilt '+p.angle+'° · bed '+p.bedRotation+'°'+(p.supportMeshes.length?' · '+p.supportMeshes.length+' ribs':''));}else if(p?.gripRange)facts.push('Grip '+p.gripRange.map(x=>x.toFixed(1)).join('–')+' mm');$('selected-info').textContent=p?facts.join('\n'):'Select a part';$('selected-info').title=p?.gripRange?'Grip excludes washers, nuts and thread engagement.':'';if(viewer){viewer.selected=selected;viewer.rebuild();}buttons();}
function generate(){clearTimeout(timer);$('export-status').textContent='';try{const p=validate(read()),next=build(p);const supportChanged=Boolean(model?.p.supports)!==Boolean(p.supports);model=next;valid=true;$('spacing-settings').hidden=!p.adaptiveJoints;$('joint-result').textContent=p.jointStyle?(model.ringPhases.length>1?'Offsets '+model.ringPhases.map(a=>(a*180/Math.PI).toFixed(1)+'°').join(' / ')+' · ':'')+model.parts.filter(x=>x.kind==='bridge').reduce((s,x)=>s+x.qty,0)+' saddles':'';$('joint-settings').hidden=!p.jointStyle;$('hardware-type').textContent=p.jointStyle?'M4 bolts · rear hex nut pockets':'M4 bolts · washers and loose nuts';$('mount-pattern').textContent='4 × M4 / '+(p.jointStyle?60:40)+' mm BCD';$('facet-settings').hidden=!p.rearStyle;$('rib-settings').hidden=!p.supports;$('support-legend').hidden=!p.supports;$('print-result').textContent=model.parts.filter(x=>x.kind==='panel').map(x=>`R${x.row+1} · tilt ${x.angle}° · bed ${x.bedRotation}°${p.supports?' · '+x.supportMeshes.length+' ribs':''}`).join(' · ');$('error').hidden=true;$('fit-badge').textContent='Fits bed';$('fit-badge').classList.remove('bad');$('model-title').textContent=`${p.diameter} / ${model.layout.n}P${model.layout.rows>1?' × '+model.layout.rows+'R':''}`;$('depth-stat').innerHTML=`${model.depth.toFixed(1)} <small>mm</small>`;$('focal-stat').innerHTML=`${model.focal.toFixed(1)} <small>mm</small>`;$('count-stat').innerHTML=`${model.parts.reduce((s,p)=>s+p.qty,0)} <small>/ ${model.parts.length} unique</small>`;$('volume-stat').innerHTML=`${(model.parts.reduce((s,p)=>s+volume(p.mesh)*p.qty,0)/1000).toFixed(0)} <small>cm³</small>`;$('bolts').textContent=model.bolts;$('parts').replaceChildren(...model.parts.map(p=>{const b=document.createElement('button');b.className='part-row '+p.kind;b.dataset.id=p.id;b.setAttribute('aria-pressed','false');b.innerHTML=`<span class="part-swatch" aria-hidden="true"></span><span class="part-name">${p.name}<small>${p.dim.map(x=>x.toFixed(1)).join(' × ')} mm</small></span><span class="qty">×${p.qty}</span>`;b.onclick=()=>select(p.id);return b;}));selected='';if(viewer){if(supportChanged&&viewer.mode==='layout')viewer.pitch=(p.supports||p.rearStyle||p.jointStyle) ? 0.85 : 0.25;viewer.selected='';viewer.setModel(model);}profile(model);$('selected-info').textContent='Select a part';buttons();return model;}catch(e){valid=false;$('error').hidden=false;$('error').textContent=e.message+(model?' Preview shows the last valid model.':'');$('fit-badge').textContent='Needs adjustment';$('fit-badge').classList.add('bad');buttons();return null;}}
function schedule(){valid=false;buttons();clearTimeout(timer);timer=setTimeout(generate,260);}
$('parameters').addEventListener('submit',e=>e.preventDefault());for(const k in defaults){$(k).addEventListener('input',()=>{if($(k+'-range'))$(k+'-range').value=$(k).value;if(k.startsWith('bed'))syncBed();if(k==='adaptiveJoints')$('spacing-settings').hidden=!$('adaptiveJoints').checked;if(k==='jointStyle')$('joint-settings').hidden=!Number($('jointStyle').value);if(k==='rearStyle'){$('facet-settings').hidden=!Number($('rearStyle').value);if(Number($('rearStyle').value)&&Number($('printAngle').value)===0)$('printAngle').value='-1';}if(k==='supports'){$('rib-settings').hidden=!$('supports').checked;if($('supports').checked)document.querySelector('[data-view=layout]').click();}schedule();});if($(k+'-range'))$(k+'-range').addEventListener('input',()=>{$(k).value=$(k+'-range').value;schedule();});}
$('bedPreset').addEventListener('change',()=>{if($('bedPreset').value==='custom')return;const [x,y,z]=$('bedPreset').value.split(',');$('bedX').value=x;$('bedY').value=y;$('bedZ').value=z;generate();});$('reset').onclick=()=>{setFields(defaults);generate();};$('home').onclick=()=>viewer?.reset();
for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>{for(const x of document.querySelectorAll('[data-view]')){x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b?'true':'false');}$('explosion-control').hidden=b.dataset.view!=='exploded';$('view-caption').textContent=b.dataset.view==='layout'?'Individual print beds':'';if(viewer){viewer.mode=b.dataset.view;if(viewer.mode==='layout'){viewer.pitch=(model?.p.supports||model?.p.rearStyle||model?.p.jointStyle) ? 0.85 : 0.25;viewer.yaw=0;viewer.zoom=1;}else viewer.reset();viewer.rebuild();}};
$('rear-view').onclick=()=>{document.querySelector('[data-view=assembled]').click();if(viewer){viewer.pitch=2.3;viewer.draw();}};
$('focus').onchange=()=>{if(viewer){viewer.focus=$('focus').checked;viewer.rebuild();}};$('wire').onchange=()=>{if(viewer){viewer.wire=$('wire').checked;viewer.rebuild();}};$('explosion').oninput=()=>{if(viewer){viewer.explode=Number($('explosion').value);viewer.rebuild();}};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function exporting(fn){if(!valid||busy)return;busy=true;buttons();$('export-status').textContent='Preparing your files…';try{await new Promise(r=>setTimeout(r,30));await fn();$('export-status').textContent='Download prepared.';}catch(e){$('export-status').textContent=e.message;}finally{busy=false;buttons();}}
$('export-part').onclick=()=>exporting(()=>{const p=model.parts.find(p=>p.id===selected);if(!p)throw Error('Select a part first.');download(new Blob([binarySTL(p.output)],{type:'model/stl'}),`${p.id}${p.supportMeshes.length?'_supported':''}_qty-${p.qty}.stl`);});$('export-all').onclick=()=>exporting(async()=>{const snapshot=model;download(kit(snapshot,await kernelPromise),`PETAL-${snapshot.p.diameter}mm-print-kit.zip`);});$('export-scad').onclick=()=>exporting(async()=>{const snapshot=model;download(new Blob([scadSource(snapshot,await kernelPromise)],{type:'text/plain'}),'petal.scad');});
const narrow=matchMedia('(max-width:1100px)');
let panel='';
function setPanel(next,restore=true){
 const previous=panel;panel=narrow.matches?next:'';
 if(panel)document.body.dataset.panel=panel;else delete document.body.dataset.panel;
 $('panel-shade').hidden=!panel;
 document.querySelector('.stage-column').inert=Boolean(panel);
 for(const name of ['design','parts']){
  const el=$(name+'-panel'),active=name===panel;
  $(name+'-toggle').setAttribute('aria-expanded',String(active));
  el.inert=narrow.matches&&!active;
  if(active){el.setAttribute('role','dialog');el.setAttribute('aria-modal','true');}
  else{el.removeAttribute('role');el.removeAttribute('aria-modal');}
 }
 if(panel)$(panel+'-panel').querySelector('[data-close-panel]').focus();
 else if(previous&&restore)$(previous+'-toggle').focus();
}
for(const name of ['design','parts'])$(name+'-toggle').onclick=()=>setPanel(panel===name?'':name);
document.querySelectorAll('[data-close-panel]').forEach(b=>b.onclick=()=>setPanel(''));
$('panel-shade').onclick=()=>setPanel('');
narrow.addEventListener('change',()=>setPanel('',false));setPanel('',false);
document.addEventListener('keydown',e=>{
 if(!panel||$('guide').open)return;
 if(e.key==='Escape'){e.preventDefault();setPanel('');}
 if(e.key==='Tab'){
  const items=[...$(panel+'-panel').querySelectorAll('button,input,select,summary,a[href],[tabindex="0"]')].filter(el=>!el.disabled&&el.getClientRects().length);
  const first=items[0],last=items.at(-1);
  if(e.shiftKey&&(document.activeElement===first||!$(panel+'-panel').contains(document.activeElement))){e.preventDefault();last?.focus();}
  else if(!e.shiftKey&&(document.activeElement===last||!$(panel+'-panel').contains(document.activeElement))){e.preventDefault();first?.focus();}
 }
});
$('guide-toggle').onclick=()=>{setPanel('',false);$('guide').showModal();$('guide-toggle').setAttribute('aria-expanded','true');};
$('guide-close').onclick=()=>$('guide').close();
$('guide').addEventListener('close',()=>{$('guide-toggle').setAttribute('aria-expanded','false');$('guide-toggle').focus();});

generate();
// Optional browser agent interface; it shares the visible form and generation path.
if(document.modelContext?.registerTool){const abort=new AbortController();window.addEventListener('pagehide',()=>abort.abort(),{once:true});const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:abort.signal})).catch(()=>{});}catch{}};
register({name:'inspect_dish_geometry',description:'Read the current valid dish dimensions, print parts and quantities. Does not download files.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return valid?manifest(model):{error:'The form has invalid settings.'};}});
register({name:'configure_dish_geometry',description:'Update geometric and printer parameters in the visible form and regenerate the model. Does not download files.',inputSchema:{type:'object',properties:Object.fromEntries(Object.entries(limits).map(([k,[min,max]])=>[k,{type:'number',minimum:min,maximum:max}])),additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Array.isArray(input))throw Error('Expected an object.');for(const k in input)if(!(k in defaults))throw Error(`Unknown setting: ${k}`);for(const [k,v] of Object.entries(input)){const el=$(k);if(el.tagName==='SELECT'&&![...el.options].some(o=>o.value===String(v)))throw Error(`Choose an available option for ${k}.`);}const p=validate({...read(),...input});build(p);setFields(p);const m=generate();if(!m)throw Error('Model generation failed.');return{diameter:m.p.diameter,petals:m.layout.n,rings:m.layout.rows,unique_parts:m.parts.length};}});}
